import{I as a}from"./ImageSection-f91dbdc6.js";import{_ as t}from"./_plugin-vue_export-helper-c27b6911.js";import{b as s,c as d,e,F as i,k as o}from"./index-6e7b86a6.js";const c="/assets/paster01-8bc7347b.jpg",r="/assets/paster02-c6ff2b02.jpg",l="/assets/city_lights-9d653ad3.png";const v=o('<section class="about-section" data-v-83da82f2><div class="container" data-v-83da82f2><article class="pastor-block reverse" data-aos="fade-up" data-v-83da82f2><div class="pastor-img" data-v-83da82f2><div class="img-frame" data-v-83da82f2><img src="'+c+'" alt="高文聰牧師" data-v-83da82f2></div><div class="img-accent" aria-hidden="true" data-v-83da82f2></div></div><div class="pastor-info" data-v-83da82f2><div class="pastor-role" data-v-83da82f2>PASTOR</div><h2 data-v-83da82f2>教會牧師 — 高文聰</h2><p data-v-83da82f2>2021年12月，高文聰牧師本於對福音的熱情開拓磐石之心教會，期望能在新興教會與傳統教會中取得平衡。在教會中首要任務是講明福音的本質，使信徒得著福音的好處，實踐在生活各個層面中。在教導上，強調聖經為教會的權威。致力教導聖經神學、聖約神學、以基督為中心的講道、福音轉化、西敏信條…等。每周在線上帶領以救贖歷史框架查考聖經，使信徒進入整本聖經的偉大救贖圖畫中，等候末世最後的成全。</p><ul class="pastor-timeline" data-v-83da82f2><li data-v-83da82f2>2019年6月 台北改革宗神學院道學碩士畢業</li><li data-v-83da82f2>2019年7月 CITY to CITY TAIWAN 植堂者訓練結業</li><li data-v-83da82f2>2020年4月 台中烈火教會擔任傳道人</li><li data-v-83da82f2>2020年9月 晨曦福音戒毒學院兼任教師</li><li data-v-83da82f2>2021年12月 開拓磐石之心教會</li></ul></div></article><article class="pastor-block" data-aos="fade-up" data-v-83da82f2><div class="pastor-img" data-v-83da82f2><div class="img-frame" data-v-83da82f2><img src="'+r+'" alt="黃宗儀牧師" data-v-83da82f2></div><div class="img-accent" aria-hidden="true" data-v-83da82f2></div></div><div class="pastor-info" data-v-83da82f2><div class="pastor-role" data-v-83da82f2>SUPERVISOR</div><h2 data-v-83da82f2>教會監督 — 黃宗儀</h2><p data-v-83da82f2>黃宗儀牧師是華神校友，曾在客西馬尼行道會，台中精誠教會（開拓），費城台福教會及台中福音基督教會牧會，黃宗儀牧師在獲得英國牛津宣教研究中心的哲學博士之後，曾在中台神學院專任教學，現為黃藥師的福音神學教室的創辦人，致力於為教會客製化神學課程，把神學帶進教會，將福音神學的核心真理透過解經，神學及實踐的課程轉化生命。基督教今日報專訪：擁叛逆靈魂　從小提琴手、牙醫到牧師：盼不要自居為「比較好的罪人」</p><div class="pastor-links" data-v-83da82f2><a href="https://www.facebook.com/HYSClassroom?locale=zh_TW" target="_blank" rel="noopener noreferrer" class="pastor-btn" data-v-83da82f2>福音神學教室</a><a href="https://tinyurl.com/bfmnxjwz" target="_blank" rel="noopener noreferrer" class="pastor-btn outline" data-v-83da82f2>比較好的罪人</a></div></div></article></div></section><section class="city-section" data-v-83da82f2><img class="img-fluid" data-aos="fade-up" src="'+l+'" alt="城市燈光" data-v-83da82f2></section>',2),f={__name:"AboutView",setup(n){return(p,m)=>(s(),d(i,null,[e(a,{title:"關於我們","background-image":"url(https://hexschool-api.s3.us-west-2.amazonaws.com/custom/U8YjSv6kB6Hfx6uYp42LSDTcZ6fPUvRSqzIhvWeaPGjyHqjlLFV7FSKJZijzQEFsRsgbjPfuK7M4Ai7Pvk15Gz3gyHFEa2O2lEQ0HxXysp1GEQH0MQsuNdMkXcCCvcy9.jpg)"}),v],64))}},b=t(f,[["__scopeId","data-v-83da82f2"]]);export{b as default};
